<script id="hstu-health-arcade-script">
(function(){
  const play=document.getElementById('hstuArcadePlay');
  const back=document.getElementById('hstuArcadeBack');
  const overlay=document.getElementById('hstuArcadeOverlay');
  if(!play||!back||!overlay)return;
  const frame=document.getElementById('hstuArcadeFrame');
  function openArcade(){
    if(frame && (frame.src==='about:blank' || frame.src.endsWith('about:blank'))){
      frame.src=frame.dataset.gameSrc || './health-snake.html';
    }
    overlay.classList.add('open');
    overlay.setAttribute('aria-hidden','false');
    document.body.classList.add('hstu-arcade-open');
  }
  function closeArcade(){
    overlay.classList.remove('open');
    overlay.setAttribute('aria-hidden','true');
    document.body.classList.remove('hstu-arcade-open');
    /* Stop the game loop completely when leaving the Arcade. */
    if(frame) frame.src='about:blank';
  }
  play.addEventListener('click',openArcade);
  back.addEventListener('click',closeArcade);
  if(frame){
    frame.addEventListener('load',function(){
      if(frame.src && !frame.src.endsWith('about:blank')){
        setTimeout(function(){
          try{frame.contentWindow.focus();}catch(e){}
        },100);
      }
    });
  }
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&overlay.classList.contains('open'))closeArcade()});
})();
</script>
